import{onetQuestions,scoreOnetInterest}from'./onet-assessment.js';
import{explorerResults,explorerCareerQuestions,explorerAnswer}from'./open-explorer-087.js';
import{saveExplorerAnswer}from'./explorer-053-state.js';
import{escapeHTML as h}from'./html.js';
export const followupProfileKey083=s=>JSON.stringify(onetQuestions.map(q=>s.profileJourney?.officialInterest?.answers?.[q.id]??null))+'|087';
export function selectAutomaticFollowups083(s){if(!scoreOnetInterest(s).complete)return[];const rows=explorerResults(s).rows.filter(r=>!r.specific.supported&&!r.specific.contrary.length&&(r.r>=.608||r.activityTopics?.length||r.specific.evidence.length)),groups=rows.map(r=>({r,qs:explorerCareerQuestions(r.id).filter(q=>!explorerAnswer(s,'profession',r.id,q))})).filter(g=>g.qs.length&&g.qs.length<=12),chosen=[],fields=new Set();let count=0;
const choose=g=>{if(chosen.includes(g)||chosen.length>=3||count+g.qs.length>12||g.r.o.noncollege087&&chosen.filter(x=>x.r.o.noncollege087).length>=2)return false;chosen.push(g);count+=g.qs.length;fields.add(g.r.fields[0]);return true;};
// Reserve one chance for a direct activity that a broad six-theme average can miss.
// The other slots retain the existing evidence-first, field-diverse order.
const anchors=groups.filter(g=>g.r.directActivity087).sort((a,b)=>Number(b.r.activityTopics.some(id=>['onet-sf-37','onet-sf-25','onet-sf-26'].includes(id)))-Number(a.r.activityTopics.some(id=>['onet-sf-37','onet-sf-25','onet-sf-26'].includes(id)))||(b.r.r??-2)-(a.r.r??-2)||a.qs.length-b.qs.length);if(anchors.length)choose(anchors[0]);
for(const distinct of[true,false])for(const g of groups){if(distinct&&fields.has(g.r.fields[0]))continue;choose(g);}return chosen.flatMap(g=>g.qs.map(q=>({careerId:g.r.id,questionId:q.id})));}

export function automaticRoundDue083(s){return scoreOnetInterest(s).complete&&(s.explorer053?.followupRound083?.profileKey!==followupProfileKey083(s)||(s.explorer053?.followupRound083?.cursor??0)<(s.explorer053?.followupRound083?.queue?.length??0));}
export function beginAutomaticFollowups083(s){if(!scoreOnetInterest(s).complete)return'journey/explore';s.explorer053??={version:1,facetAnswers:{},fieldAnswers:{},professionAnswers:{},history:[]};let r=s.explorer053.followupRound083;if(!r||r.profileKey!==followupProfileKey083(s)||r.queue.some(item=>!explorerCareerQuestions(item.careerId).some(q=>q.id===item.questionId))){const queue=selectAutomaticFollowups083(s);r=s.explorer053.followupRound083={profileKey:followupProfileKey083(s),queue,cursor:0};}return r.cursor<r.queue.length?'journey/match-followup/'+r.cursor:'journey/explore';}
export function automaticQuestion083(s,index){const round=s.explorer053?.followupRound083;if(!round||round.profileKey!==followupProfileKey083(s)||!Number.isInteger(index)||index<0||index>round.cursor)return null;const item=round.queue[index];if(!item)return null;const q=explorerCareerQuestions(item.careerId).find(q=>q.id===item.questionId);return q?{round,item,q}:null;}
export function saveAutomaticAnswer083(s,index,payload){const entry=automaticQuestion083(s,index);if(!entry)return null;saveExplorerAnswer(s,{kind:'profession',scope:entry.item.careerId,questionId:entry.q.id,payload});entry.round.cursor=index+1;return entry.round.cursor<entry.round.queue.length?'journey/match-followup/'+entry.round.cursor:'journey/explore';}
export function automaticFollowupPage083(s,index){const entry=automaticQuestion083(s,index);if(!entry)return '<section class="guide-input-panel"><h1>Continue your interest follow-ups</h1><button class="button" data-action="explorer-auto-begin">Continue →</button></section>';const{round,item,q}=entry,a=explorerAnswer(s,'profession',item.careerId,q),specific=['specific','core-work'].includes(q.kind),attrs=`data-index="${index}" data-question="${h(q.id)}"`;return `<header class="page-intro"><div><span class="eyebrow">A CLOSER LOOK AT YOUR INTERESTS</span><h1>What appeals to you?</h1><p class="intro-copy">Follow-up ${index+1} of ${round.queue.length}</p></div></header><section class="guide-input-panel interest-question-card"><h2 id="followup-activity">${h(q.prompt)}</h2>${specific?`<fieldset class="interest-answer-group" aria-labelledby="followup-activity"><legend class="sr-only">Choose your response</legend><div class="interest-response-grid followup-response-grid">${[['yes','I would like to learn this'],['no','This does not interest me'],['unsure','Unsure'],['unfamiliar','I need to learn more']].map(([v,t])=>`<button type="button" class="button secondary" data-action="explorer-auto-response" ${attrs} data-value="${v}" aria-pressed="${a?.response===v}">${t}</button>`).join('')}</div></fieldset>`:`<form id="automatic-followup-answer"><fieldset class="interest-answer-group"><legend>Choose any examples that appeal</legend>${q.options.map(o=>`<label class="followup-choice"><input type="checkbox" name="automatic-option" value="${h(o.id)}" ${a?.selected?.includes(o.id)?'checked':''}><span>${h(o.text)}</span></label>`).join('')}</fieldset><div class="interest-response-grid followup-response-grid"><button type="button" class="button" data-action="explorer-auto-task" ${attrs}>Continue →</button>${[['none','None appeal'],['unsure','Unsure'],['unfamiliar','I need to learn more']].map(([v,t])=>`<button type="button" class="button secondary" data-action="explorer-auto-task" ${attrs} data-feedback="${v}">${t}</button>`).join('')}</div><p id="automatic-followup-error" role="status"></p></form>`}${index?`<nav class="interest-question-nav"><a class="button secondary" href="#/journey/match-followup/${index-1}">← Previous</a></nav>`:''}</section>`;}
